import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  /* config options here */
};

export default nextConfig;

import "server-only";

import Database from "better-sqlite3";

// One SQLite handle, shared by Better Auth (src/lib/auth.ts) and the user
// queries in src/lib/users.ts. Cached on globalThis so the dev server's hot
// reload reuses the handle instead of leaking a new one on every edit.
const globalForDb = globalThis as unknown as { notelyDb?: Database.Database };

function open(): Database.Database {
  const db = new Database(process.env.DATABASE_PATH ?? "notely.sqlite");
  db.pragma("journal_mode = WAL");
  return db;
}

export const db = (globalForDb.notelyDb ??= open());

import "server-only";

import { headers } from "next/headers";

import { auth } from "./auth";
import { db } from "./db";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

// Shape of Better Auth's `user` table. It stores timestamps as an ISO string on
// some drivers and as epoch milliseconds on others, so accept both.
type UserRow = {
  id: string;
  email: string;
  name: string | null;
  createdAt: string | number | Date | null;
};

function toDay(value: UserRow["createdAt"]): string {
  if (value == null) return "unknown";
  const date =
    typeof value === "string" && /^\d+$/.test(value)
      ? new Date(Number(value))
      : new Date(value);
  return Number.isNaN(date.getTime()) ? "unknown" : date.toISOString().slice(0, 10);
}

function toUser(row: UserRow): User {
  return {
    id: row.id,
    // Google accounts always carry a name; email sign-ups could still leave it
    // blank, so fall back to the local part of the address.
    name: row.name?.trim() || row.email.split("@")[0],
    email: row.email,
    createdAt: toDay(row.createdAt),
  };
}

const SELECT_USER = `select id, email, name, createdAt from "user"`;

export async function listUsers(): Promise<User[]> {
  const rows = db
    .prepare(`${SELECT_USER} order by createdAt asc`)
    .all() as UserRow[];
  return rows.map(toUser);
}

export async function getUser(id: string): Promise<User | undefined> {
  const row = db.prepare(`${SELECT_USER} where id = ?`).get(id) as
    | UserRow
    | undefined;
  return row && toUser(row);
}

/**
 * The signed-in user for the current request, or undefined when there is no
 * valid session. This reads the Better Auth session cookie and verifies it
 * against the database, so it is safe to gate rendering on.
 */
export async function getCurrentUser(): Promise<User | undefined> {
  const session = await auth.api.getSession({ headers: await headers() });
  return session ? toUser(session.user as UserRow) : undefined;
}

